     9→namespace DayZ
    10→{
    11→    /// <summary>
    12→    /// 对象池管理器
    13→    /// </summary>
    14→    public class ObjectPoolManager
    15→    {
    16→        #region Instance
    17→        private static ObjectPoolManager instance;
    18→        private ObjectPoolManager() { }
    19→        public static ObjectPoolManager Instance { get { if (instance == null) instance = new ObjectPoolManager(); return instance; } }
    20→        #endregion
    21→
    22→        /// <summary>
    23→        /// 对象池注册信息，用于FreeObject无法集成接口无法添加特性是使用。
    24→        /// </summary>
    25→        /// <typeparam name="Type">对象类型</typeparam>
    26→        /// <typeparam name="UnalterabObjectPoolValueStruct"></typeparam>
    27→        Dictionary<int, ObjectPoolValueStruct> typeRegister = new Dictionary<int, ObjectPoolValueStruct>()
    28→        {
    29→            {typeof(List<string>).GetHashCode(),new ListObjectPoolValueStruct<string>()}
    30→        };
    31→
    32→        /// <summary>
    33→        /// 对象池集合
    34→        /// </summary>
    35→        /// <typeparam name="int">对象类型的哈希值</typeparam>
    36→        /// <typeparam name="IReusableObjectPool"></typeparam>
    37→        /// <returns></returns>
    38→        Dictionary<int, IReusableObjectPool> poolCollection = new Dictionary<int, IReusableObjectPool>();
    39→
    40→        /// <summary>
    41→        /// 对象池集合
    42→        /// </summary>
    43→        /// <typeparam name="Type">对象类型的哈希值</typeparam>
    44→        /// <typeparam name="IReusableObjectPool">对象池</typeparam>
    45→        Dictionary<int, IReusableObjectPool> freePoolCollection = new Dictionary<int, IReusableObjectPool>();
    46→
    47→
    48→
    49→
    50→
    51→        #region Pool
    52→
    53→        IReusableObjectPool GetPool<T>() where T : class, IReusableObject, new()
    54→        {
    55→            int hashcode = typeof(T).GetHashCode();
    56→            if (poolCollection.ContainsKey(hashcode))
    57→            {
    58→                return poolCollection[hashcode];
    59→            }
    60→            else
    61→            {
    62→                InterfaceReusableObjectPool<T> pool = new InterfaceReusableObjectPool<T>();
    63→                poolCollection.Add(hashcode, pool);
    64→                return pool;
    65→            }
    66→        }
    67→
    68→
    69→        public T GetReusableObject<T>(object user) where T : class, IReusableObject, new()
    70→        {
    71→            if (GetPool<T>() is IReusableObjectPool pool && pool != null)
    72→            {
    73→                return (T)pool.GetReusableObject(user);
    74→            }
    75→            throw new NullReferenceException();
    76→        }
    77→
    78→
    79→        /// <summary>
    80→        /// 回收一个可回收对象。
    81→        /// </summary>
    82→        /// <param name="target">要回收的目标对象</param>
    83→        public void RecycleReusableObject<T>(T target) where T : class, IReusableObject, new()
    84→        {
    85→            int hashcode = target.GetType().GetHashCode();
    86→            if (GetPool<T>() is IReusableObjectPool pool && pool != null)
    87→            {
    88→                pool.RecycleReusableObject(target);
    89→            }
    90→        }
    91→
    92→        #endregion
    93→
    94→
    95→        #region FreePool
    96→
    97→        /// <summary>
    98→        /// 获取一个对象池。
    99→        /// 如果没有，尝试创建一个。
   100→        /// </summary>
   101→        /// <param name="type">目标类型</param>
   102→        /// <returns>目标对象池，如果目标类型无法创建对象池，返回空。</returns>
   103→        IReusableObjectPool GetFreePool(Type type)
   104→        {
   105→            int hashcode = type.GetHashCode();
   106→            if (poolCollection.ContainsKey(hashcode))
   107→            {
   108→                return poolCollection[hashcode];
   109→            }
   110→            else if (freePoolCollection.ContainsKey(hashcode))
   111→            {
   112→                return freePoolCollection[hashcode];
   113→            }
   114→            else
   115→            {
   116→                if (typeRegister.ContainsKey(hashcode))
   117→                {
   118→                    ConfigReusableObjectPool pool = new ConfigReusableObjectPool(type, typeRegister[hashcode]);
   119→                    freePoolCollection.Add(hashcode, pool);
   120→                    return pool;
   121→                }
   122→                else if (type.IsDefined(typeof(ReusableObjectAttribute), false))
   123→                {
   124→                    ReusableObjectAttribute attribute = Attribute.GetCustomAttribute(type, typeof(ReusableObjectAttribute)) as ReusableObjectAttribute;
   125→                    AttributeReusableObjectPool pool = new AttributeReusableObjectPool(type, attribute.InitialNum);
   126→                    freePoolCollection.Add(hashcode, pool);
   127→                    return pool;
   128→                }
   129→                else
   130→                {
   131→                    return null;
   132→                }
   133→
   134→            }
   135→        }
   136→
   137→        /// <summary>
   138→        /// 获取一个目标类型的可回收对象。
   139→        /// </summary>
   140→        /// <param name="user">使用者，用来标识对象基本信息，用于检查和Debug，没有实际作用。</param>
   141→        /// <param name="parameters">可回收对象初始化参数，请保证参数与目标类型的初始化方法参数一致。</param>
   142→        /// <typeparam name="T">目标类型</typeparam>
   143→        /// <returns>转换成目标类型的可回收对象，如果目标类型无法创建可回收对象，返回Default。</returns>
   144→        public T GetFreeReusableObject<T>(object user, object[] parameters) where T : new()
   145→        {
   146→            Type type = typeof(T);
   147→
   148→            var pool = GetFreePool(type);
   149→            if (pool == null)
   150→            {
   151→                throw new NullReferenceException();
   152→            }
   153→            if (pool is IFreeReusableObjectPool)
   154→            {
   155→                return (T)(pool as IFreeReusableObjectPool).GetReusableObject(user, parameters);
   156→            }
   157→            else
   158→            {
   159→                return (T)pool.GetReusableObject(user);
   160→            }
   161→
   162→
   163→            throw new NullReferenceException();
   164→        }
   165→
   166→        /// <summary>
   167→        /// 回收一个可回收对象。
   168→        /// </summary>
   169→        /// <param name="target">要回收的目标对象</param>
   170→        public void RecycleFreeReusableObject(object target)
   171→        {
   172→            Type type = target.GetType();
   173→            if (GetFreePool(type) is IFreeReusableObjectPool pool && pool != null)
   174→            {
   175→                pool.RecycleReusableObject(target);
   176→            }
   177→        }
   178→        #endregion
   179→    }
   180→
   181→    public static class IReusableObjectExt
   182→    {
   183→        public static T New<T>(this T iobject, string tag) where T : class, IReusableObject, new()
   184→        {
   185→            return ObjectPoolManager.Instance.GetReusableObject<T>(tag);
   186→        }
   187→
   188→        public static void Recycle<T>(this T iobject) where T : class, IReusableObject, new()
   189→        {
   190→            ObjectPoolManager.Instance.RecycleReusableObject<T>(iobject);
   191→        }
   192→
   193→    }
   194→}

