     8→    /// </summary>
     9→    /// <typeparam name="TKey"></typeparam>
    10→    /// <typeparam name="TValue"></typeparam>
    11→    public class DictionaryPool<TKey, TValue>
    12→    {
    13→        /// <summary>
    14→        /// 栈对象：存储多个字典
    15→        /// </summary>
    16→        static Stack<Dictionary<TKey, TValue>> mListStack = new Stack<Dictionary<TKey, TValue>>(8);
    17→
    18→        /// <summary>
    19→        /// 出栈：从栈中获取某个字典数据
    20→        /// </summary>
    21→        /// <returns></returns>
    22→        public static Dictionary<TKey, TValue> GetDictionaryObject()
    23→        {
    24→            if (mListStack.Count == 0)
    25→            {
    26→                return new Dictionary<TKey, TValue>(8);
    27→            }
    28→
    29→            return mListStack.Pop();
    30→        }
    31→
    32→        /// <summary>
    33→        /// 回收字典对象
    34→        /// </summary>
    35→        /// <param name="target">要回收的字典对象</param>
    36→        public static void Recycle(Dictionary<TKey, TValue> target)
    37→        {
    38→            target.Clear();
    39→            mListStack.Push(target);
    40→        }
    41→    }
    42→}

