     9→namespace DayZ
    10→{
    11→    /// <summary>
    12→    /// 标准的对象池，使用特性标注可回收对象的初始化方法，回收属性以及回收方法。
    13→    /// </summary>
    14→    class AttributeReusableObjectPool : IFreeReusableObjectPool
    15→    {
    16→        #region TypeInfo
    17→        /// <summary>
    18→        /// 该对象池存储的类型
    19→        /// </summary>
    20→        Type type;
    21→
    22→        /// <summary>
    23→        /// 对象初始化方法集合。如果要使用多个，必须保证所有方法的参数一致。
    24→        /// </summary>
    25→        List<MethodInfo> initMethodList = new List<MethodInfo>();
    26→
    27→        /// <summary>
    28→        /// 需要还原的属性集合
    29→        /// </summary>
    30→        List<PropertyInfo> restoredPropertyList = new List<PropertyInfo>();
    31→
    32→        /// <summary>
    33→        /// 还原方法集合
    34→        /// </summary>
    35→        List<MethodInfo> restoredMethodList = new List<MethodInfo>();
    36→
    37→
    38→        public AttributeReusableObjectPool(Type type, int initialNum)
    39→        {
    40→            this.type = type;
    41→
    42→            initMethodList = new List<MethodInfo>(type.GetMethods().Where(q => q.IsDefined(typeof(ReusableInitMethodAttribute))));
    43→
    44→            restoredPropertyList = new List<PropertyInfo>(type.GetProperties().Where(q => q.IsDefined(typeof(ReusableRestoredPropertyAttribute))));
    45→
    46→            restoredMethodList = new List<MethodInfo>(type.GetMethods().Where(q => q.IsDefined(typeof(ReusableRestoredMethodAttribute))));
    47→
    48→
    49→            for (int i = 0; i < initialNum; i++)
    50→            {
    51→                unactivatedPool.Push(Activator.CreateInstance(type));
    52→            }
    53→        }
    54→
    55→        /// <summary>
    56→        /// 初始化可回收对象。
    57→        /// </summary>
    58→        /// <param name="target">目标可回收对象。</param>
    59→        /// <param name="parameter">初始化参数。</param>
    60→        void InitReusableObject(object target, object[] parameter)
    61→        {
    62→            foreach (MethodInfo method in initMethodList)
    63→            {
    64→                method.Invoke(target, parameter);
    65→            }
    66→        }
    67→
    68→        /// <summary>
    69→        /// 还原一个可回收对象。
    70→        /// </summary>
    71→        /// <param name="target">目标可回收对象</param>
    72→        void RestoreReusableObject(object target)
    73→        {
    74→            foreach (PropertyInfo property in restoredPropertyList)
    75→            {
    76→                property.SetValue(target, default);
    77→            }
    78→            foreach (MethodInfo method in restoredMethodList)
    79→            {
    80→                method.Invoke(target, null);
    81→            }
    82→        }
    83→        #endregion
    84→
    85→        #region Reusable
    86→
    87→        /// <summary>
    88→        /// 空闲池
    89→        /// </summary>
    90→        Stack<object> unactivatedPool = new Stack<object>();
    91→
    92→#if UNITY_EDITOR
    93→        /// <summary>
    94→        /// 激活池
    95→        /// </summary>
    96→        Dictionary<object, (int, object)> activatedPool = new Dictionary<object, (int, object)>();
    97→
    98→        public object GetReusableObject(object user)
    99→        {
   100→            object target = unactivatedPool.Count != 0 ? unactivatedPool.Pop() : Activator.CreateInstance(type);
   101→
   102→            return target;
   103→        }
   104→
   105→        public object GetReusableObject(object user, object[] parameters)
   106→        {
   107→            object target = unactivatedPool.Count != 0 ? unactivatedPool.Pop() : Activator.CreateInstance(type);
   108→
   109→            InitReusableObject(target, parameters);
   110→            activatedPool.Add(target, (0, user));
   111→
   112→            return target;
   113→        }
   114→
   115→        public void RecycleReusableObject(object target)
   116→        {
   117→            if (!activatedPool.ContainsKey(target))
   118→            {
   119→                Debug.LogError("回收重用对象" + type + "时，活动池中未包含目标对象");
   120→            }
   121→            else
   122→            {
   123→                activatedPool.Remove(target);
   124→            }
   125→
   126→            RestoreReusableObject(target);
   127→            unactivatedPool.Push(target);
   128→
   129→            foreach (var kv in activatedPool)
   130→            {
   131→                int flag = kv.Value.Item1 + 1;
   132→                if (flag > 500)
   133→                {
   134→                    Debug.LogError(kv.Value.Item2 + "使用的可重用对象" + type + "长时间未回收。");
   135→                }
   136→                activatedPool[kv.Key] = (flag, kv.Value.Item2);
   137→            }
   138→
   139→        }
   140→
   141→#else
   142→
   143→        public object GetReusableObject(object user)
   144→        {            
   145→            object target = unactivatedPool.Count != 0 ? unactivatedPool.Pop() : Activator.CreateInstance(type);
   146→
   147→            return target;
   148→        }
   149→
   150→        public object GetReusableObject(object user, object[] parameters)
   151→        {
   152→            object target = unactivatedPool.Count != 0 ? unactivatedPool.Pop() : Activator.CreateInstance(type);
   153→
   154→            InitReusableObject(target, parameters);
   155→
   156→            return target;
   157→        }
   158→        public void RecycleReusableObject(object target)
   159→        {
   160→            RestoreReusableObject(target);
   161→            unactivatedPool.Push(target);
   162→        }
   163→#endif
   164→        #endregion
