    36→
    37→        public ConfigReusableObjectPool(Type type, ObjectPoolValueStruct value)
    38→        {
    39→            this.type = type;
    40→
    41→            this.createFunction = value.createFunction;
    42→            this.initAction = value.initAction;
    43→            this.restoredAction = value.restoredAction;
    44→
    45→            for (int i = 0; i < value.initialNum; i++)
    46→            {
    47→                unactivatedPool.Push(CreateReusableObject());
    48→            }
    49→        }
    50→
    51→        /// <summary>
    52→        /// 创建可回收对象。
    53→        /// </summary>
