    55→        object CreateReusableObject()
    56→        {
    57→            object obj = null;
    58→            if (createFunction != null)
    59→            {
    60→                obj = createFunction.Invoke();
    61→            }
    62→            else
    63→            {
    64→                obj = Activator.CreateInstance(type);
    65→            }
    66→
    67→            if (obj.GetType() == type)
    68→            {
    69→                return obj;
    70→            }
    71→            else
    72→            {
    73→                return null;
    74→            }
    75→        }
    76→
    77→        /// <summary>
